int iov_to_skb(struct sk_buff *skb, const struct iovec *from, int offset, size_t count) {
    const struct iovec *iov;
    size_t len = 0;
    int i;

    for (i = offset; i < count; ++i) {
        len += from[i].iov_len;
    }

    iov = from + offset;

    if (!iov) {
        return -EFAULT;
    }

    if (!skb->head) {
        skb->head = kmalloc(len, GFP_KERNEL);
        if (!skb->head) {
            return -ENOMEM;
        }
        skb->data = skb->head;
        skb->len = len;
        skb->truesize += len;
    }

    for (i = 0; i < count; ++i) {
        char __user *src = iov[i].iov_base;
        size_t len = iov[i].iov_len;

        if (copy_from_user(skb->data, src, len)) {
            return -EFAULT;
        }

        skb->data += len;
    }

    skb->tail = skb->data;
    skb->end = skb->data;

    return 0;
}

int skb_copy_from_iovec(struct sk_buff *skb, const struct iovec *from, int offset, size_t count)
{
    const struct iovec *iov;
    struct page *page;
    unsigned int len, copied = 0;
    int i;

    for (i = offset; i < count; ++i) {
        iov = &from[i];
        len = iov->iov_len;

        if (copied + len > iov->iov_len) {
            return -EFAULT;
        }

        if (!skb->len) {
            if (len <= skb_headroom(skb)) {
                if (copy_from_user(skb->data - len, iov->iov_base, len))
                    return -EFAULT;
                skb->data -= len;
                skb->len += len;
            } else {
                page = alloc_page(GFP_KERNEL);
                if (!page)
                    return -ENOMEM;
                if (copy_from_user(page_address(page), iov->iov_base, len))
                    return -EFAULT;
                skb_fill_page_desc(skb, 0, page, 0, len);
                skb->len += len;
            }
        } else {
            if (len <= skb_tailroom(skb)) {
                if (copy_from_user(skb_put(skb, len), iov->iov_base, len))
                    return -EFAULT;
            } else {
                page = alloc_page(GFP_KERNEL);
                if (!page)
                    return -ENOMEM;
                if (copy_from_user(page_address(page), iov->iov_base, len))
                    return -EFAULT;
                skb_fill_page_desc(skb, skb_shinfo(skb)->nr_frags, page, 0, len);
                skb_shinfo(skb)->nr_frags++;
                skb->len += len;
            }
        }
        copied += len;
    }

    return 0;
}

int skb_copy_datagram_iovec(struct sk_buff *skb, const struct iovec *from, int offset, size_t count)
{
    size_t len = 0;
    int i;

    for (i = 0; i < count; i++) {
        len += from[i].iov_len;
    }

    if (offset + len > skb->data_len) {
        return -EFAULT;
    }

    for (i = 0; i < count; i++) {
        const struct iovec *iov = &from[i];
        size_t copy = iov->iov_len;
        char __user *buf = iov->iov_base;

        if (copy == 0) {
            continue;
        }

        if (copy > skb_tailroom(skb)) {
            return -EFAULT;
        }

        if (copy > iov->iov_len - offset) {
            copy = iov->iov_len - offset;
        }

        if (copy > 0) {
            if (copy_from_user(skb->data, buf + offset, copy)) {
                return -EFAULT;
            }

            skb_put(skb, copy);
            offset += copy;
        }
    }

    return 0;
}

int iov_to_skb_copy(struct sk_buff *skb, const struct iovec *from, int offset, size_t count) {
    int i;
    size_t total_len = 0;
    int ret;

    for (i = 0; i < count; i++) {
        total_len += from[i].iov_len;
    }

    for (i = 0; i < count; i++) {
        const void __user *buf = from[i].iov_base + offset;
        size_t len = from[i].iov_len - offset;

        if (len <= 0) {
            continue;
        }

        if (skb->len + len > skb->truesize) {
            return -EFAULT;
        }

        ret = skb_add_data(skb, buf, len);
        if (ret < 0) {
            return ret;
        }

        offset = 0;
    }

    return 0;
}

int iov_to_skb(struct sk_buff *skb, const struct iovec *from, int offset, size_t count) {
    size_t len = 0;
    size_t total_len = 0;
    const struct iovec *iov;
    int i;

    for (i = 0; i < count; i++) {
        iov = &from[i];
        len = iov->iov_len;
        total_len += len;
    }

    if (!skb->data_len) {
        skb->data_len = total_len;
        skb->len += total_len;
    }

    for (i = 0; i < count; i++) {
        iov = &from[i];
        len = iov->iov_len;
        if (len == 0)
            continue;

        if (iov->iov_base == NULL)
            return -EFAULT;

        if (copy_from_user(skb->head + skb->tail, iov->iov_base + offset, len))
            return -EFAULT;

        skb->tail += len;
        offset = 0;
    }

    return 0;
}
